-- GENERATED by `wfj generate` from data/gossip/gossip-f8.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f80849030f802d82"] = { "Ho bisogno di addestramento.", "." },
  ["f81160c76f3234ae"] = { "Hai combattuto bene, spirito. Ti chiedo di concedermi la forza del tuo corpo e la forza del tuo cuore.", "." },
  ["f818d784821d6c15"] = { "Certo, {name}.\n\nGli avventurieri che l'Alba considera Osannati devono consegnare in totale 12 insegne per accedere agli oggetti superiori. Per accedere a oggetti di potere ancora maggiore, dovrebbero consegnarne in totale 54.\n\nChi è Osannato agli occhi dell'Alba riceve gli sconti maggiori.", "." },
  ["f8194b8434e9f6cb"] = { "Avete fame, porcellini? Ho del cibo per voi...", "." },
  ["f8276e75c5531bff"] = { "Posso chiederti cosa ci fai qui? Indossa la tua tenuta da studente e studia!", "." },
  ["f8292503c790f320"] = { "Chi osa provocare il messaggero di Edwin Van Cleef? Muori, {race}!", "." },
  ["f8314c39188f4573"] = { "Sì, sì, sì! Sei proprio <il/la> {race} che cercavo!\n\nSiediti! Abbiamo molto di cui parlare!!", "." },
  ["f855dbdf3bab6b02"] = { "I mortali sono caduti! La nuova era della legione ⟦Blackrock=Roccianera⟧ è vicina!", "." },
  ["f85da2b44f6e9764"] = { "Lava? Non badarci, amico. Guardati intorno. Goditi le gioie che la natura ha da offrire.", "." },
  ["f869d21e57e4296b"] = { "⟦Hegnar Rumbleshot=Hegnar Granzuffa⟧, al tuo servizio!", "." },
  ["f86d4d23ee9341ea"] = { "Salve, <signore/signora>... hai un po' di tempo per darci una mano? Per favore?", "." },
  ["f8709a27513dc3dd"] = { "Cos'è stato?! Trey? TREY!?", "." },
  ["f87ad0cf3169f31d"] = { "Non sei un po' <basso/bassa> per quelli della tua razza?", "." },
  ["f884f5407448429c"] = { "Ti strapperò i segreti dalla carne!", "." },
  ["f8866dfb070153d3"] = { "Grazie ancora per il tuo aiuto. Che il vento ti sia sempre alle spalle nei tuoi viaggi.", "." },
  ["f88cf8f77ed5f9d2"] = { "Grazie, mortale. C'è un solo servigio che posso offrirti prima di tornare nel Sogno.\n\nLa porta del padrone di Zevrim, Alzzin, ti sbarra la strada. Sarò il tuo strumento di distruzione. La porta verrà aperta: attendo soltanto il tuo comando.", "." },
  ["f88f842eea0ad39b"] = { "⟦Anachronos=Anacronos⟧, ho perso l'anello con sigillo. Potresti darmene uno nuovo?", "." },
  ["f890233dde0bfb04"] = { "Queste corse sono un'ottima occasione per mostrare il nostro ingegno!", "." },
  ["f891dde0bc453959"] = { "Non mi serve una casa per sapere di avere ancora un posto in questo mondo, {class}. Le tribù vedranno... tutte quante. Combattono tra loro, e per cosa? Gli avanzi lasciati dagli avvoltoi... terre infestate dalla Legione... bah!\n\nI centauri dovrebbero andare fieri della loro stirpe, nobile quanto quella di qualsiasi elfo della notte o orco: è ora che cominciamo a comportarci di conseguenza!", "." },
  ["f893d2c0f37fdbbd"] = { "In tutti i nostri anni di rapporti con gli spiriti del vento, mai una volta hanno parlato del Signore del Vento come di una figura da venerare. Riconoscevano l'esistenza di un essere chiamato Al'Akir, ma evitavano di invocarne il nome, quasi come se lo temessero.\n\nAnche se questo Al'Akir fosse un onnipotente \"Signore del Vento\" o il sovrano degli elementali del vento, i miei secoli di comunione con gli spiriti mi hanno convinto che, quantomeno, non è amato da tutti gli abitanti di Skywall. Temo che tentare di trattare con Al'Akir potrebbe soltanto affrettare la nostra rovina.", "." },
  ["f89d2a658247a8b3"] = { "Ho perso il mio ⟦Shroud of Infinite Wisdom=Manto della Saggezza Infinita⟧. Puoi sostituirmelo?", "." },
  ["f8a23ae9a496759f"] = { "%s cerca aiuto!", "." },
  ["f8a8134ca76103de"] = { "Cerco delle guardie del corpo disposte a proteggere la ⟦Gizelton Caravan=Carovana di Lentecurva⟧. Siamo fermi sulla strada a est del ⟦Kormek's Hut=Capanno di Kormek⟧, a nord del Kolkar Centaur Village.", "." },
  ["f8a99c02e2203806"] = { "Più vicino, ora. Bocconi gustosi. È passato troppo tempo senza cibo, senza sangue da bere.", "." },
  ["f8ab0ebe9d789b2f"] = { "I capitani dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧ sono caduti! Sconfiggete ⟦Drek'Thar=Drek'thar⟧ prima che sia troppo tardi!", "." },
  ["f8adacc29eea64cf"] = { "Quelli della nostra specie sono rari di questi tempi, ma tra gli Shen'dorei c'è ancora chi sogna nello smeraldo.", "." },
  ["f8ae37281ce489fc"] = { "Quando ti guardavo storto prima che tu diventassi <il/la> <nuovo/nuova> <re/regina>... ehm... stavo solo scherzando.\n\nGià!", "." },
  ["f8af897fe367e1e9"] = { "Buona giornata, <ragazzo/ragazza>. Posso esserti utile?", "." },
  ["f8b396f83b64e536"] = { "Io e le mie sorelle siamo scese dalle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧ per porre fine a una tragedia di epoche passate. Purtroppo non siamo abbastanza forti per raggiungere i nostri obiettivi da sole, e ora cerchiamo mortali come te che ci aiutino.\n\nSe sei abbastanza potente, allora abbiamo molto di cui parlare, {class}. Se non lo sei, per la tua sicurezza lascerò fuori dalla nostra conversazione i dettagli della mia missione.", "." },
  ["f8ba3d479fdcd448"] = { "NO!!! Lui mette il tannino nel cesto, o si becca di nuovo il maglio!", "." },
  ["f8c15a266ea8d528"] = { "Proprio mentre parliamo, {class}, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧. A quanto pare, dovrebbe arrivare tutto in meno di $2113w giorni. Dopodiché, <un/una> <eroe/eroina> dovrà venire a suonare il gong sull'Altare dello Scarabeo. Allora la guerra comincerà davvero.", "." },
  ["f8c188a1259de17e"] = { "<Benvenuto/Benvenuta> alla ⟦Great Forge=Grande Forgia⟧, <ragazzo/ragazza>. Fuori farà anche freddo, ma qui sotto lo teniamo bello caldo. Prendi un martello, colpisci quell'incudine e mostrami che hai la stoffa per essere un Fabbro della ⟦Great Forge=Grande Forgia⟧!", "." },
  ["f8c7831d83541096"] = { "Non merito questa conversazione, <padrone/padrona>.", "." },
  ["f8c995c722778d86"] = { "Ahh... I miei esperimenti non riescono mai bene. Forse dovrei tornare a valle.", "." },
  ["f8cada86748ecd3b"] = { "Notevole, {name}. Hai un talento per uccidere che non percepivo in nessun altro da molti anni. Persino Molthor sa del lavoro che hai svolto per Zandalar. È tempo di potenziare ancora il tuo talismano. Dammelo.", "." },
  ["f8d71922439ee5af"] = { "Le tue abilità in alchimia non sono ancora abbastanza elevate per trarre beneficio dai miei insegnamenti. Forse, se mi parli più avanti...", "." },
  ["f8d918a57a3c2f01"] = { "Accesso: ⟦Discombobulator Ray=Raggio Ricombinante⟧", "." },
  ["f8da48f2caad2e06"] = { "Sei fuori di testa.", "." },
  ["f8e020ca3c020615"] = { "Gri'lek, del Sangue di Ferro\n\nIl viandante. Che la sua forza e la sua sete di battaglia attraversino le ere.\n\nOra Gri'lek indugia ai confini della follia...", "." },
  ["f8e1e0202f7c372a"] = { "Ho freddo, mio signore. Quando manterrai la tua promessa?", "." },
  ["f8e554b46426cf88"] = { "%s sibila.", "." },
  ["f8e779785fc3cd9d"] = { "Cane! Ora intrappolerò la tua anima in un frammento e ti darò al mio imp come giocattolo!", "." },
  ["f8e9a1aab2f3e759"] = { "Ce l'abbiamo fatta!", "." },
  ["f8ef26e8317afc17"] = { "Thrall ha pagato bene me e i miei ragazzi per aver aiutato a costruire Orgrimmar, così ho deciso di aprire un porto qui. Facciamo la maggior parte dei nostri affari tramite la ⟦Booty Bay=Baia del Bottino⟧ e il barone Revilgaz.", "." },
  ["f8fa296bab4c5f46"] = { "Parrebbe, <caro/cara>, che l'⟦Alliance=Alleanza⟧ sia riuscita a raccogliere tutto il necessario per lo sforzo bellico. Ora non ci resta che aspettare che quelle povere creature dell'⟦Horde=Orda⟧ finiscano con il loro.", "." },
})
